const $=id=>document.getElementById(id);let rows=[];
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=d=>d?new Date(d).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):'—';
const days=(a,b)=>Math.max(0,Math.floor((new Date(b)-new Date(a))/86400000));
const parseAmount=s=>{let v=String(s).trim().replace(/\s|R\$/g,'');if(v.includes(','))v=v.replace(/\./g,'').replace(',','.');const n=Number(v);return Number.isFinite(n)&&n>=0?Math.round(n*100)/100:null};
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const msg=s=>{$('message').textContent=s;setTimeout(()=>{if($('message').textContent===s)$('message').textContent=''},6000)};
async function api(action,{method='GET',body,params}={}){const url='/api/'+action+(params?'?'+new URLSearchParams(params):'');const r=await fetch(url,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Erro na operação');return d}
function show(id){['setup','login','app'].forEach(x=>$(x).hidden=x!==id);$('logout').hidden=id!=='app'}
function tab(id){document.querySelectorAll('.tab').forEach(e=>e.hidden=e.id!==id);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===id));if(id==='reports')loadReports()}
function printVoucher(v){$('printArea').innerHTML=`<div class="center"><strong>TEX PUB</strong><div>VALE-CHOPE • RETORNO</div><hr><div class="code">${escapeHtml(v.code)}</div><hr></div><div>Emitido: ${date(v.issued_at)}</div><div>Validade: ${date(v.expires_at)}</div>${v.customer_name?`<div>Cliente: ${escapeHtml(v.customer_name)}</div>`:''}<p>Apresente este comprovante junto ao vale-chope físico. Prazo de 30 dias. Após o prazo, sujeito à autorização da casa.</p><div class="center">Aguardamos sua volta!</div><div class="print-logo"><img src="data:image/png;base64," alt="TEX PUB"></div>`;const img=$("printArea").querySelector("img");if(img.complete){window.print()}else{img.onload=()=>window.print();img.onerror=()=>{msg("Logo não carregou; verifique o arquivo no GitHub.");window.print()}}}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('login',{method:'POST',body:{password:$('password').value}});$('password').value='';show('app')}catch(err){msg(err.message)}};
$('logout').onclick=async()=>{await api('logout',{method:'POST'});show('login')};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
$('issueForm').onsubmit=async e=>{e.preventDefault();const a=parseAmount($('amount').value);if(a===null){msg('Informe um valor válido');return}const btn=$('issueBtn');btn.disabled=true;try{const {voucher:v}=await api('issue',{method:'POST',body:{amount:a,customer:$('customer').value.trim(),issuer:$('issuer').value}});$('issued').hidden=false;$('issued').innerHTML=`<strong>Vale emitido!</strong><br>Código: <strong>${escapeHtml(v.code)}</strong><br>Valor inicial: ${money(v.first_amount)}<br>Validade: ${date(v.expires_at)}<br><button id="reprint" class="secondary">Reimprimir o mesmo vale</button>`;$('reprint').onclick=()=>printVoucher(v);$('amount').value='';$('customer').value='';printVoucher(v)}catch(err){msg(err.message)}finally{btn.disabled=false}};
$('lookupForm').onsubmit=async e=>{e.preventDefault();try{const {voucher:v}=await api('lookup',{params:{code:$('lookupCode').value.trim().toUpperCase()}});const box=$('found');box.hidden=false;if(!v){box.textContent='Código não encontrado.';return}const late=Date.now()>new Date(v.expires_at).getTime(),used=!!v.redeemed_at;box.innerHTML=`<h3>${escapeHtml(v.code)} — ${used?'JÁ UTILIZADO':late?'VENCIDO (resgate excepcional permitido)':'VÁLIDO'}</h3><div>Cliente: ${escapeHtml(v.customer_name||'Não informado')}</div><div>Emissão: ${date(v.issued_at)} · Consumo: ${money(v.first_amount)}</div><div>Prazo: ${date(v.expires_at)}</div>${used?`<div>Resgatado em ${date(v.redeemed_at)} após ${days(v.issued_at,v.redeemed_at)} dias · Retorno: ${money(v.return_amount)}</div>`:`<div>Tempo decorrido: ${days(v.issued_at,new Date())} dias</div><form id="redeemForm"><label>Consumo na visita de retorno (R$)<input id="returnAmount" inputmode="decimal" required placeholder="Ex.: 120,00"></label><button>${late?'Autorizar resgate fora do prazo':'Confirmar resgate'}</button></form>`}`;if(!used)$('redeemForm').onsubmit=async ev=>{ev.preventDefault();const a=parseAmount($('returnAmount').value);if(a===null){msg('Informe o valor do retorno');return}if(!confirm(`Confirmar resgate de ${v.code} com consumo de ${money(a)}?${late?' Vale vencido: autorização excepcional.':''}`))return;try{await api('redeem',{method:'POST',body:{code:v.code,amount:a,allowLate:late}});msg('Resgate confirmado!');$('lookupForm').requestSubmit()}catch(err){msg(err.message)}}}catch(err){msg(err.message)}};
const isoLocal=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const now=new Date();$('from').value=isoLocal(new Date(now.getFullYear(),now.getMonth(),1));$('to').value=isoLocal(now);
async function loadReports(){const from=$('from').value,to=$('to').value;if(!from||!to||from>to){msg('Período inválido');return}try{const data=await api('reports',{params:{from,to}});rows=data.rows;const redeemed=rows.filter(v=>v.redeemed_at),late=redeemed.filter(v=>v.redeemed_late);const avg=redeemed.length?redeemed.reduce((s,v)=>s+days(v.issued_at,v.redeemed_at),0)/redeemed.length:0;const stats=[['Vales emitidos no período',rows.length],['Resgatados desta emissão',redeemed.length],['Taxa de retorno',rows.length?(redeemed.length/rows.length*100).toFixed(1)+'%':'0%'],['Resgates fora do prazo',late.length],['Dias até retorno',avg.toFixed(1)],['Consumo de retornos no período',money(data.returns.total)]];$('stats').innerHTML=stats.map(([label,value])=>`<div class="stat"><b>${escapeHtml(value)}</b><span>${escapeHtml(label)}</span></div>`).join('');$('reportRows').innerHTML=rows.map(v=>`<tr><td>${escapeHtml(v.code)}</td><td>${escapeHtml(v.customer_name||'—')}</td><td>${date(v.issued_at)}</td><td>${money(v.first_amount)}</td><td>${v.redeemed_at?(v.redeemed_late?'Resgatado fora do prazo':'Resgatado'):(new Date()>new Date(v.expires_at)?'Vencido':'Pendente')}</td><td>${date(v.redeemed_at)}</td><td>${v.redeemed_at?days(v.issued_at,v.redeemed_at):'—'}</td><td>${v.redeemed_at?money(v.return_amount):'—'}</td></tr>`).join('');if(data.truncated)msg('Relatório limitado a 10 mil registros.')}catch(err){msg(err.message)}}
$('refresh').onclick=loadReports;
$('export').onclick=()=>{const cols=['codigo','nome','emissao','validade','emissor','consumo_inicial','status','data_retorno','dias_retorno','consumo_retorno','fora_prazo'];const csv=[cols.join(';'),...rows.map(v=>[v.code,v.customer_name||'',date(v.issued_at),date(v.expires_at),v.issued_by,Number(v.first_amount).toFixed(2).replace('.',','),v.redeemed_at?'Resgatado':'Pendente',date(v.redeemed_at),v.redeemed_at?days(v.issued_at,v.redeemed_at):'',v.redeemed_at?Number(v.return_amount).toFixed(2).replace('.',','):'',v.redeemed_late?'Sim':'Não'].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';'))].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tex-vales-${$('from').value}-a-${$('to').value}.csv`;a.click();URL.revokeObjectURL(url)};
api('session').then(d=>show(d.authenticated?'app':'login')).catch(()=>show('setup'));
